export const RESERVED_FORM_FIELD_KEYS = [
  'fullName',
  'documentType',
  'documentNumber',
  'dateOfBirth',
  'email',
  'phone',
  'vehicleMake',
  'vehicleModel',
  'vehicleYear',
  'vehicleIdentifier',
  'vehicleUsage',
] as const;

